\begin{lemma}\label{le:xi2}
Here we take the ground ring to be $\C[\xx]$. 
    Fix $l$ and let $\l\vdash l+2$. For any $n\geq l+4$, there exists a unique (up to an overall scalar $\in \C[\a]$) element $\xi^{(n)}_\l\in \Delta^{(n)}_{(n-2,\l)}$ with coefficients in $\C[\a]$ 

    such that the following hold:
    \begin{enumerate}
        \item $\uu^*_{i,j} \xi^{(n)}_{\l}=0$ for all $i<j<n$ with $\uu_{i,j}\in \BBB_{(l,n)}$.
        \item $\uu^*_{n-1,n} \xi^{(n)}_{\l}=D_n(\a) c_\l $ for some $D_n(\a)\in \C[\a]$.  
    \end{enumerate}

\end{lemma}
\begin{proof}
    Existence and uniqueness follow by solving a (full rank) linear problem which is analogous to the proof of Lemma \ref{lem:xi}. 
\end{proof}
\begin{lemma}\label{lem:cxi} Fix $l$ and let $\l\vdash l+2$. For any $n\geq l+4$, let $\xi^{(n)}_\l\in \Delta^{(n)}_{(n-2,\l)}$ be as per Lemma \ref{le:xi2} (with a fixed normalisation, \textit{i.e.} choice of $D_n(\a)$). Then, with $\a$ generic (i.e. working over $\C[\a]$) we have $c_\l  \xi^{(n)}_\l=\xi^{(n)}_\l$, with $c_\l\in J_{l,n}$ as per \ref{de:cl}.   
\end{lemma}
\begin{proof} 
It will be clear from the proof of \ref{lem:niceelt}, and idempotency of $c_\l$, that $c_\l  \xi^{(n)}_\l$ also satisfies conditions 1. and 2. from the previous lemma (with the same factor $D_n(\a)$) thus the desired equality follows by uniqueness of $\xi_\l$.

\end{proof}

\mdef\label{pa:spechbas} For the remainder of this section, fix a basis $\BB=\{b_1,\dots, b_{d_\l}\}$ for $\SS_\l$, which is orthonormal wrt $\langle \_,\_ \rangle$ and for which $b_1=c_\l$, and $b_k=x_k c_\l$ for some $x_k\in \C \Sigma_{l+2}$. It follows from Lemma \ref{lem:cxi} that the coefficient of $u_{n-1,n}b_k$ in $\xi^{(n)}_{\l}$ is only non-zero when $k=1$, since 
\[ c_\l u_{n-1,n}b_k  =u_{n-1,n}c_\l x_k c_\l =\langle b_1, b_k \rangle u_{n-1,n}  c_\l,\]
and since $c_\l u_{ij}$ for $j<n$ can be written as a linear combination $\sum_{i'<j'<n} u_{i'j'} \sigma_{i'j'}$ for $\sigma_{i'j'}\in \C\Sigma_{l+2}$, by ``pulling" cups up through each permutation in $c_\l$.

\mdef \label{de:xinorm} Thus far, the element $\xi^{(n)}_\l\in \Delta^{(n)}_{(n-2,\l)}$ is only defined up to a polynomial factor. Let us fix a choice of ``normalisation" for $\xi^{(n)}_\l\in \Delta^{(n)}_{(n-2,\l)}$. Firstly, we will assume that there is no common polynomial factor of all coefficients in $\xi^{(n)}_\l$. Thus for all specialisations $\a\in \C$, we have that $\xi^{(n)}_\l\neq 0$. This determines $\xi^{(n)}_\l$ (and hence $D_n(\a)$) up to a complex scalar. By multiplying $\xi^{(n)}_\l$ by a complex scalar, we may assume that $D_n(\a)$ is monic. In what follows we will always take $\xi^{(n)}_\l$ to be normalised as such. 


\begin{lemma} Fix $l$ and let $\l\vdash l+2$. For any $n > l+4$, the (normalised) $\xi^{(n)}_\l$ can be obtained inductively by
\begin{equation} \label{eq:ind2} \xi^{(n)}_\l = D_{n-1}(\a) \uu_{n-1,n}c_{\l}-\xi_{\l}^{(n-1)}\otimes id_1. \end{equation}
\end{lemma}

\begin{proof} Fix a basis $\BB=\{b_1,\dots, b_{d_\l}\}$ for $\SS_\l$ as per \ref{pa:spechbas}. Let $\xi_{\l}^{(n-1)}$ be as per \ref{de:xinorm} with $\uu_{n-2,n-1}^*\xi_{\l}^{(n-1)}=D_{n-1}(\a)$. Then define
\[\xi:= D_{n-1}(\a) \uu_{n-1,n}c_{\l}-\xi_{\l}^{(n-1)}\otimes id_1.\]
Since $\xi_{\l}^{(n-1)}\otimes id_1$ has no components of the form $\uu_{n-1,n} b_k$ it follows that the coefficients in $\xi$ have no common non-trivial factor, since those in $\xi_{\l}^{(n-1)}\otimes id_1$ didn't.

Now observe for any $i<j<n-1$, for $u_{ij}\in \BBB_{(l,n)}$ we have
\[ \uu_{ij}^*\xi=D_{n-1}(\a) \uu_{ij}^*\uu_{n-1,n}c_{\l}-(\uu_{ij}^*\xi_{\l}^{(n-1)})\otimes id_1=0.\]
using the property 1 from from Lemma \ref{le:xi2}. Using property 2. we have 
\begin{align*}
    \uu_{n-2,n-1}^*\xi&=D_{n-1}(\a) \uu_{n-2,n-1}^*\uu_{n-1,n}c_{\l}-(\uu_{n-2,n-1}^*\xi_{\l}^{(n-1)})\otimes id_1\\
    &=D_{n-1}(\a)c_\l-D_{n-1}(\a)c_\l=0.
\end{align*}
Now note that 
\[\uu_{n-1,n}^* (\xi_{\l}^{(n-1)}\otimes id_1)=[\xi_{\l}^{(n-1)}]_{n-2,n-1,1 }\uu_{n-1,n}^*\uu_{n-2,n-1} c_\l=[\xi_{\l}^{(n-1)}]_{n-2,n-1,1 } c_\l,\]
since $\uu_{n-1,n}^*\uu_{i,j}$ has $n-4$ propagating lines for $j<n-1$, and the only non-zero components of the form $\uu_{n-2,n-1}b_{k}$ in $\xi_{\l}^{(n-1)}$ have $k=1$. Therefore, we compute that 
\[\uu_{n-2,n-1}^*\xi =(\a D_{n-1}(\a)-[\xi_{\l}^{(n-1)}]_{n-2,n-1,1 })c_\l,\]
so $\xi$ satisfies 1. and 2. from Lemma \ref{le:xi2}, with $D_n(\a)=(\a D_{n-1}(\a)-[\xi_{\l}^{(n-1)}]_{n-2,n-1,1 })$. Therefore, by uniqueness $\xi= a \xi^{(n)}_\l$ for some factor $a\in \C$. We will now verify that $a=1$, that is $D_n(\a)$ is monic.

Firstly, we treat the case $n=l+5$. For $\xi^{(l+5)}_\l$ as defined by the recursion \eqref{eq:ind2} we have that $D_{l+5}(\a)=\a D_{l+4}(\a) +[\xi_\l]_{l+3,l+4,1}$, where $\xi_\l^{(l+4)}=\xi_\l$ is as per Lemma \ref{lem:xi}. In the proof of Lemma \ref{lem:pl}, we saw that 
\[
\frac{D_{l+5}(\a)}{D_{l+4}(\a)}=\frac{\a D_{l+4}(\a)+[\xi_\l]_{l+3,l+4,1}}{D_{l+4}(\a)}=\frac{P_{l+5}^{(\l)}(\a)}{P_{l+4}^{(\l)}(\a)}.
\]
Since the $P_{n}^{(\l)}(\a)$ are monic for $n\geq l+4$, it follows that if $D_{l+4}(\a)$ is taken to be monic, then $D_{l+5}(\a)$ will be too. Thus $\xi^{(l+5)}_\l$ as defined by \eqref{eq:ind2} is normalised as per \ref{de:xinorm}. 

Now for $n>l+5$, by applying \eqref{eq:ind2} twice we find
\[D_{n}(\a)=\a D_{n-1}(\a)+[\xi_{\l}^{(n-1)}]_{n-2,n-1,1 }=\a D_{n-1}(\a)+D_{n-2}(\a),\]
which implies $D_{n}$ is monic, since $D_{l+4}$ and $D_{l+5}$ were, and satisfy $\deg(D_{l+5})=\deg(D_{l+4})+1$, in addition.\end{proof}

\begin{corollary}\label{co:PdivD} Fix $l$ and let $\l\vdash l+2$. For any $n > l+4$, the (normalised) element $\xi^{(n)}_\l\in \Delta^{(n)}_{(n-2,\l)}$ satisfies $u_{n-1,n}^* \xi^{(n)}_\l=D_n(\a) c_\l$ where $P_n^{(\l)}(\a)$ divides $D_n(\a)$.
\end{corollary} 

\begin{proof}
Since for $n>l+5$, the $D_n(\a)$ obey the Chebyshev recursion \eqref{eq:Cheby0}, the claim now follows from the previous proof, where we had
\[\frac{D_{l+5}(\a)}{D_{l+4}(\a)}=\frac{P_{l+5}^{(\l)}(\a)}{P_{l+4}^{(\l)}(\a)},\]
which implies $D_{l+4}(\a)=f(\a) P^{(\l)}_{l+4}(\a)$ and $D_{l+5}(\a)=f(\a) P^{(\l)}_{l+5}(\a)$ for some $f(\a)\in \C[\a]$, since the series $P^{(\l)}_{n}$ has no common non-trivial factor.
\end{proof}


\begin{theorem} Fix $l$ and let $\l\vdash l+2$. Let $n\geq l+4$, and suppose $\a_0\in \C$ is such that $P_n^{(\l)}(\a_0)=0$. 
Then 
\ppmm{when the algebra parameter $\xx=\xx_0$ we have that} 
$J_{l,n} \xi^{(n)}_\l$ is a submodule of $\Delta^{(n)}_{(n-2,\l)}$ isomorphic to $\Delta^{(n)}_{(n,\l)}$. 


\end{theorem} 
\begin{proof} 
Firstly, we note that $\xi^{(n)}_\l$ is non-zero after specialisation at $\a=\a_0$ and satisfies $c_\l \xi^{(n)}_\l=\xi^{(n)}_\l$, and $u_{n-1,n}^* \xi^{(n)}_\l=D(\a_0) c_\l=0$ by Corollary \ref{co:PdivD}. In particular, combining with condition 1. from Lemma \ref{le:xi2} we have $J_{l,n}^{n-2} \xi^{(n)}_{\l}=0$ (where $J_{l,n}^{p}$ is as per \ref{de:Jln}). Since $J_{l,n}=\C \Sigma_{l+2}\oplus J_{l,n}^{n-2}$ we compute (as $\C$ vector spaces):
\begin{align*} J_{l,n}\xi^{(n)}_\l&=\C \Sigma_{l+2} \xi^{(n)}_\l= \C \Sigma_{l+2} c_\l \xi^{(n)}_\l,   
\end{align*}
    It follows that the $b_i \xi^{(n)}_\l= x_i \xi^{(n)}_\l $ span $J_{l,n}\xi^{(n)}_\l$, where $\BB=\{b_1,\dots, b_{d_{\l}}\}$ is a basis for $\C \Sigma_{l+2} c_\l \simeq \SS_\l$ as per \ref{pa:spechbas}. To see they are linearly independent we argue as follows: suppose that $\sum_k a_k b_k \xi^{(n)}_\l=0$ for some coefficients $a_k\in \C$. Multiplying by $c _\l x_{i}^*$, we obtain then
    \[
    0=\sum_k a_k c _\l x_{i}^* x_k c_\l \xi^{(n)}_\l=\sum_k a_k \langle b_k, b_i\rangle c_\l \xi^{(n)}_\l= a_i c_\l \xi^{(n)}_\l =a_i \, \xi^{(n)}_\l,
    \]
    which implies $a_i=0$ for all $i$. It therefore follows that $x c_\l \mapsto x c_\l \xi_\l^{(n)} $ for $x\in J_{l,n}$ is a \bajmm{monomorphism} $\Delta^{(n)}_{(n,\l)}\to \Delta^{(n)}_{(n-2,\l)} $ 

    of $J_{l,n}$ modules. 
    \end{proof}

